import { createHash } from "crypto";

export interface FlagRule {
  key: string;
  enabled: boolean;
  rolloutPercent: number;
  allowTenants: string[];
  denyTenants: string[];
}

export interface EvalContext {
  userId: string;
  tenantId: string;
}

export class FlagEvaluator {
  private rules = new Map<string, FlagRule>();

  load(rules: FlagRule[]): void {
    const next = new Map<string, FlagRule>();
    for (const r of rules) {
      if (r.rolloutPercent < 0 || r.rolloutPercent > 100) {
        throw new RangeError(`flag ${r.key}: rolloutPercent out of range`);
      }
      next.set(r.key, r);
    }
    this.rules = next;
  }

  isEnabled(key: string, ctx: EvalContext): boolean {
    const flag = this.rules.get(key);
    if (!flag || !flag.enabled) return false;
    if (flag.denyTenants.includes(ctx.tenantId)) return false;
    if (flag.allowTenants.includes(ctx.tenantId)) return true;
    const bucket = this.bucketFor(flag.key, ctx.userId);
    return bucket <= flag.rolloutPercent;
  }

  private bucketFor(flagKey: string, userId: string): number {
    const digest = createHash("sha256").update(`${flagKey}:${userId}`).digest();
    return digest.readUInt32BE(0) % 100;
  }
}

import { FlagEvaluator } from "./flags";

export interface LoginAttempt {
  userId: string;
  tenantId: string;
  passwordOk: boolean;
  hasWebAuthn: boolean;
  hasTotp: boolean;
}

export type LoginOutcome =
  | { status: "denied"; reason: string }
  | { status: "challenge"; method: "webauthn" | "totp" }
  | { status: "granted" };

export class LoginPolicy {
  constructor(private readonly flags: FlagEvaluator) {}

  decide(a: LoginAttempt): LoginOutcome {
    if (!a.passwordOk) return { status: "denied", reason: "invalid_credentials" };
    const ctx = { userId: a.userId, tenantId: a.tenantId };

    if (this.flags.isEnabled("passkey-first-login", ctx) && a.hasWebAuthn) {
      return { status: "challenge", method: "webauthn" };
    }
    if (a.hasTotp) {
      return { status: "challenge", method: "totp" };
    }
    if (this.flags.isEnabled("require-mfa-enrollment", ctx)) {
      return { status: "denied", reason: "mfa_enrollment_required" };
    }
    return { status: "granted" };
  }
}
